<?php
require_once '../config/db.php'; require_once '../includes/auth.php'; require_role(['Admin','Property Officer']);
$pdo->exec("CREATE TABLE IF NOT EXISTS scheme_definitions (id INT AUTO_INCREMENT PRIMARY KEY, scheme_name VARCHAR(150) NOT NULL, scheme_address VARCHAR(255) NOT NULL, sector_details TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)");
$message=''; if ($_SERVER['REQUEST_METHOD']==='POST') { $name=trim($_POST['scheme_name']??''); $address=trim($_POST['scheme_address']??''); $details=trim($_POST['sector_details']??''); if($name===''||$address===''||$details===''){ $message='All fields are required.'; } else { $s=$pdo->prepare('INSERT INTO scheme_definitions (scheme_name, scheme_address, sector_details) VALUES (?,?,?)'); $s->execute([$name,$address,$details]); $message='Scheme definition saved.'; }} $schemes=$pdo->query('SELECT * FROM scheme_definitions ORDER BY id DESC')->fetchAll();
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Scheme Definition</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/css/style.css" rel="stylesheet"></head><body><div class="portal-wrapper"><header class="portal-header"><div class="portal-brand">🏗️ Scheme Definition</div><div class="portal-header-actions"><a href="admin.php" class="btn btn-sm btn-outline-light">Dashboard</a><a href="../logout.php" class="btn btn-sm btn-light">Logout</a></div></header><main class="portal-main"><div class="portal-page-header"><h1 class="portal-page-title">Scheme Definition</h1><p class="portal-page-subtitle">Scheme ke sectors, blocks aur sides define karein.</p></div><?php if($message): ?><div class="alert alert-info"><?= htmlspecialchars($message) ?></div><?php endif; ?><div class="row g-4"><div class="col-lg-5"><div class="dashboard-shell"><h5>Add Scheme Definition</h5><form method="post"><label class="form-label">Scheme Name</label><input name="scheme_name" class="form-control mb-3" required><label class="form-label">Scheme Address</label><textarea name="scheme_address" class="form-control mb-3" required></textarea><label class="form-label">Sectors / Blocks / Sides</label><textarea name="sector_details" class="form-control mb-3" rows="5" placeholder="Sector A, Block 1, East Side..." required></textarea><button class="btn btn-primary">Save Definition</button></form></div></div><div class="col-lg-7"><div class="dashboard-shell table-responsive"><h5>Scheme List</h5><table class="table"><thead><tr><th>S.No.</th><th>Scheme</th><th>Address</th><th>Sectors / Sides</th></tr></thead><tbody><?php foreach($schemes as $i=>$s): ?><tr><td><?= $i+1 ?></td><td><?= htmlspecialchars($s['scheme_name']) ?></td><td><?= htmlspecialchars($s['scheme_address']) ?></td><td><?= nl2br(htmlspecialchars($s['sector_details'])) ?></td></tr><?php endforeach; ?><?php if(!$schemes): ?><tr><td colspan="4" class="text-center text-muted">No scheme definitions yet.</td></tr><?php endif; ?></tbody></table></div></div></div></main></div></body></html>
